import { cell, testCell, expectClose, conservation, permutationInvariance, property } from "@reckoner/stdlib";

// Caldera Components LBO — the checks worksheet.
//
// Where the Excel "before" has a Checks sheet of IF(...,"OK","BREAK") text cells
// (visible only if you go look, gating nothing), the port pins the same
// invariants as typed test cells with mandatory kinds — specification (oracle
// values generated by generate.py), metamorphic (conservation / permutation),
// and property (covenants, monotonicity, convergence).
//
// GAP (recorded in the case-study gap report): the oracle lives inline here as
// constants rather than in a fixtures/expected_values input, because the M2
// test-runner wiring (AsyncEngine.runTests → engineWorker.runSuites) resolves
// only the SUBJECT's inputs — a test's own declared inputs never reach the
// expect/relation context, even though testrunner.substituteInputs implements
// the substitution. Tests can only see subject-live inputs.

// ── oracle constants (generated: python3 generate.py → expected.json) ────────
const ORACLE = {
  ltm_ebitda: 46.27,
  entry_ev: 370.16,
  sponsor_equity: 114.8837,
  uses_total: 394.5037,
  fy2031_revenue: 289.72619642520004,
  fy2031_ebitda: 64.61326374517802,
  tlb_end_2031: 173.71651835678423,
  cash_end_2031: 23.355327214405253,
  net_debt_2031: 201.447009906443,
  net_debt_2031_avg: 199.79504427119048,
  exit_equity: 315.45910005498115,
  moic: 2.7458995493266767,
  irr: 0.22387462120837076,
  irr_avg: 0.2251537582183193,
  breakeven_exit_multiple: 7.5420183108582,
};

// Credit-agreement terms (spec constants, mirroring the Excel Checks sheet).
const COV_LEVERAGE_MAX = 6.0;
const COV_COVERAGE_MIN = 2.0;

function checkAll(checks) {
  for (const c of checks) {
    if (!c.pass) return c;
  }
  return { pass: true, message: `${checks.length} value(s) match the generated oracle` };
}

// ── LTM EBITDA ────────────────────────────────────────────────────────────────

export const ltm_vs_oracle = testCell({
  kind: "specification",
  subject: "model.ltm_ebitda",
  expect: ({ result }) => checkAll([
    expectClose(result, ORACLE.ltm_ebitda, { abs: 0.005 }),
  ]),
});

export const ltm_permutation = testCell({
  kind: "metamorphic",
  subject: "model.ltm_ebitda",
  relation: permutationInvariance({ over: "hist" }),
});

// ── sources & uses ────────────────────────────────────────────────────────────

export const su_vs_oracle = testCell({
  kind: "specification",
  subject: "model.sources_uses",
  expect: ({ result }) => checkAll([
    expectClose(result.entry_ev, ORACLE.entry_ev, { abs: 0.005 }),
    expectClose(result.sponsor_equity, ORACLE.sponsor_equity, { abs: 0.005 }),
    expectClose(result.uses, ORACLE.uses_total, { abs: 0.005 }),
  ]),
});

export const su_balances = testCell({
  kind: "property",
  subject: "model.sources_uses",
  expect: ({ result }) =>
    Math.abs(result.sources - result.uses) < 0.005 && result.sponsor_equity > 0 && result.sponsor_equity / result.uses < 0.6
      ? { pass: true, message: "sources = uses; equity cheque positive and under 60% of uses" }
      : { pass: false, message: `sources-uses = ${result.sources - result.uses}; equity share ${(result.sponsor_equity / result.uses).toFixed(3)}` },
});

export const su_conserves = testCell({
  kind: "metamorphic",
  subject: "model.sources_uses_row",
  relation: conservation({
    components: ["tlb0", "mezz0", "cash_used", "sponsor_equity"],
    equals: "uses_total",
    tol: { abs: 1e-6 },
  }),
});

// ── operating build ───────────────────────────────────────────────────────────

export const ops_vs_oracle = testCell({
  kind: "specification",
  subject: "model.operating",
  expect: ({ result }) => {
    const fy31 = result[result.length - 1];
    return checkAll([
      expectClose(fy31.revenue, ORACLE.fy2031_revenue, { abs: 0.005 }),
      expectClose(fy31.ebitda, ORACLE.fy2031_ebitda, { abs: 0.005 }),
    ]);
  },
});

export const ops_permutation = testCell({
  kind: "metamorphic",
  subject: "model.operating",
  relation: permutationInvariance({ over: "plan" }),
});

export const ops_shape = testCell({
  kind: "property",
  subject: "model.operating",
  expect: ({ result }) => {
    for (let i = 1; i < result.length; i += 1) {
      if (!(result[i].revenue > result[i - 1].revenue)) {
        return { pass: false, message: `revenue not strictly increasing at year ${result[i].year}` };
      }
      if (!(result[i].ebitda / result[i].revenue > result[i - 1].ebitda / result[i - 1].revenue)) {
        return { pass: false, message: `blended margin not expanding at year ${result[i].year}` };
      }
    }
    return { pass: true, message: "revenue grows and blended margin expands every year (the plan's shape)" };
  },
});

// ── debt schedule (beginning-balance interest) ────────────────────────────────

export const sched_rolls = testCell({
  kind: "property",
  subject: "model.debt_schedule",
  expect: ({ result }) => {
    let prior = null;
    for (const r of result) {
      if (Math.abs(r.tlb_end - (r.tlb_begin - r.mand - r.sweep)) > 0.005) {
        return { pass: false, message: `TLB roll-forward breaks in ${r.year}` };
      }
      if (Math.abs(r.net_debt - (r.tlb_end + r.mezz_end + r.rev_end - r.cash_end)) > 0.005) {
        return { pass: false, message: `net debt identity breaks in ${r.year}` };
      }
      if (prior !== null) {
        if (Math.abs(r.tlb_begin - prior.tlb_end) > 1e-9) {
          return { pass: false, message: `TLB begin ≠ prior end in ${r.year}` };
        }
        if (Math.abs(r.cash_end - (prior.cash_end + r.retained)) > 0.005) {
          return { pass: false, message: `cash roll-forward breaks in ${r.year}` };
        }
      }
      prior = r;
    }
    return { pass: true, message: `roll-forward conserves across ${result.length} years` };
  },
});

export const sched_covenants = testCell({
  kind: "property",
  subject: "model.debt_schedule",
  expect: ({ result, inputs }) => {
    const minCash = inputs.a[0].min_cash;
    for (const r of result) {
      if (r.leverage > COV_LEVERAGE_MAX) return { pass: false, message: `leverage covenant breach in ${r.year}: ${r.leverage.toFixed(3)}x` };
      if (r.coverage < COV_COVERAGE_MIN) return { pass: false, message: `coverage covenant breach in ${r.year}: ${r.coverage.toFixed(3)}x` };
      if (r.cash_end < minCash) return { pass: false, message: `liquidity breach in ${r.year}: cash ${r.cash_end.toFixed(3)} < min ${minCash}` };
      if (r.rev_end !== 0) return { pass: false, message: `revolver drawn in ${r.year} — base case is planned to never draw` };
    }
    return { pass: true, message: `leverage ≤ ${COV_LEVERAGE_MAX}x, coverage ≥ ${COV_COVERAGE_MIN}x, liquidity and undrawn revolver hold all ${result.length} years` };
  },
});

export const sched_permutation = testCell({
  kind: "metamorphic",
  subject: "model.debt_schedule",
  relation: permutationInvariance({ over: "ops" }),
});

export const sched_vs_oracle = testCell({
  kind: "specification",
  subject: "model.debt_schedule",
  expect: ({ result }) => {
    const fy31 = result[result.length - 1];
    return checkAll([
      expectClose(fy31.tlb_end, ORACLE.tlb_end_2031, { abs: 0.005 }),
      expectClose(fy31.cash_end, ORACLE.cash_end_2031, { abs: 0.005 }),
      expectClose(fy31.net_debt, ORACLE.net_debt_2031, { abs: 0.005 }),
    ]);
  },
});

// ── debt schedule (average-balance / converged circular) ─────────────────────

export const sched_avg_converges = testCell({
  kind: "property",
  subject: "model.debt_schedule_avg",
  expect: ({ result }) => {
    const total = result.reduce((acc, r) => acc + r.iterations, 0);
    if (total <= 0) return { pass: false, message: "no fixed-point iterations recorded" };
    if (total >= 200 * result.length) return { pass: false, message: "hit the iteration cap — fixed point did not converge" };
    return { pass: true, message: `fixed point converged in ${total} iterations over ${result.length} years` };
  },
});

export const sched_avg_vs_oracle = testCell({
  kind: "specification",
  subject: "model.debt_schedule_avg",
  expect: ({ result }) => {
    const fy31 = result[result.length - 1];
    return checkAll([
      expectClose(fy31.net_debt, ORACLE.net_debt_2031_avg, { abs: 0.005 }),
    ]);
  },
});

